import json
import logging

import requests
from requests.auth import HTTPBasicAuth
from taf.internal.impact_radar import log_radar

requests.packages.urllib3.disable_warnings()  # type: ignore[attr-defined]
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class RestApiError(Exception):

    def __init__(self, error):
        message = f"Error code {error['errorCode']}. {error['userMessage']}"
        super().__init__(message)


class ResponseError(Exception):
    pass


class ConnectionFailedError(Exception):
    pass


class FmHttpClient:
    def __init__(self, web_url, web_username, web_password):
        self.web_url = web_url
        self.web_username = web_username
        self.web_password = web_password

    def send_request(self, method, endpoint, headers=None,
                     params=None, cert=None, files=None, timeout=None, data=None):

        response = self._send(method, endpoint, headers=headers,
                              params=params, cert=cert, files=files, timeout=timeout, data=data)
        return self._handle_response(response)

    def _send(self, method, endpoint, headers=None,
              params=None, cert=None, files=None, timeout=None, data=None):
        url = f'https://{self.web_url}{endpoint}'
        auth = HTTPBasicAuth(username=self.web_username, password=self.web_password)
        try:
            if method == 'POST':
                log_radar(
                    "Sending NetAct request",
                    request_method=method,
                    request_url=url,
                    request_params=params,
                    request_data=json.dumps(data),
                )
                response = requests.post(url, params=params, headers=headers,
                                         cert=cert, auth=auth, verify=False,
                                         files=files, data=json.dumps(data), timeout=timeout)
            else:
                raise ValueError("HTTP method used here must be `POST`")
        except requests.exceptions.RequestException as rq_e:
            raise ConnectionFailedError(f"Connection to endpoint failed with error: {rq_e}")

        return response

    @staticmethod
    def _handle_response(response):
        logger.debug(f'REST API response: {response.text}')
        if 'Content-Type' in response.headers and 'json' in response.headers['Content-Type']:
            response = response.json()
            if 'error' in response:
                raise RestApiError(response['error'])
            elif 'page' in response:
                try:
                    return response['page']['_data']['pageResult']
                except KeyError:
                    raise ResponseError(f'Could not parse response: {response}')
        else:
            response.raise_for_status()
        return response
